class Checkout:
    def __init__(self,gateway,clock,max_attempts=3):
        self.gateway=gateway;self.clock=clock;self.max_attempts=max_attempts

    def execute(self,operation_id,payload,total_timeout=1.0):
        deadline=self.clock.now+total_timeout
        for _ in range(self.max_attempts):
            remaining=deadline-self.clock.now
            if remaining<=0:break
            try:
                return self.gateway.submit(
                    payload,operation_id=operation_id,timeout=remaining
                )
            except TimeoutError:
                # A timeout can follow a charge. Retry with the same identity.
                pass
        raise TimeoutError("checkout budget or attempts exhausted")
import uuid

class Gateway:
    def __init__(self,provider,policy):
        self.provider=provider;self.policy=policy

    def submit(self,payload,operation_id=None,timeout=None):
        limit=self.policy.per_attempt(remaining=timeout)
        key=str(uuid.uuid4()) if operation_id is None else operation_id
        return self.provider.send(payload,key,limit)
class Policy:
    def __init__(self, profile=None, assumed_timeout=0.5):
        self.profile=profile
        self.assumed_timeout=assumed_timeout

    def per_attempt(self, remaining=None):
        if remaining is not None and remaining<=0:
            raise TimeoutError("attempt budget exhausted")
        if self.profile is None:
            limit=self.assumed_timeout
        else:
            limit=max(self.profile["warm_p99"],self.profile["cold_p99"])
            limit+=self.profile["network_allowance"]
        if limit<=0:
            raise ValueError("attempt timeout must be positive")
        return limit if remaining is None else min(limit,remaining)
